from pathlib import Path
import json,html
OUT=Path(__file__).resolve().parent
plan=json.loads((OUT/'website-final-plan.json').read_text())
products=sorted([p for p in plan['products'] if p.get('public')],key=lambda p:p['retail_name'].casefold())
assert len(products)==176
esc=lambda s:html.escape(str(s),quote=True)
families=sorted({p['family'] for p in products})
head='''<style>
#boldstone-catalogue{max-width:1500px;margin:auto;padding:28px 0;color:inherit}#boldstone-catalogue *{box-sizing:border-box}#boldstone-catalogue .catalogue-intro{max-width:750px;margin:0 0 28px}#boldstone-catalogue h2{margin:0 0 12px}#boldstone-catalogue .catalogue-filters{display:flex;gap:14px;flex-wrap:wrap;align-items:end;margin:24px 0}#boldstone-catalogue label{font-size:14px;display:grid;gap:6px}#boldstone-catalogue input,#boldstone-catalogue select{font:inherit;padding:12px;border:1px solid #b5bcae;border-radius:3px;background:#fff;color:#263d30;max-width:100%}#boldstone-catalogue .catalogue-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:30px 22px}#boldstone-catalogue .sculpture-card{display:block;color:inherit;text-decoration:none}#boldstone-catalogue .sculpture-card[hidden]{display:none}#boldstone-catalogue .sculpture-card img{display:block;width:100%;height:auto;aspect-ratio:1;object-fit:contain;background:#f4f3ed;transition:transform .2s}#boldstone-catalogue .sculpture-card:hover img{transform:scale(1.015)}#boldstone-catalogue .sculpture-card:focus-visible{outline:2px solid #536d43;outline-offset:5px}#boldstone-catalogue h3{font-size:17px;line-height:1.4;margin:12px 0 4px}#boldstone-catalogue .sculpture-family{font-size:13px;opacity:.75;margin:0}#boldstone-catalogue .catalogue-count{font-size:14px;margin:0 0 20px}#boldstone-catalogue .catalogue-more{margin:32px auto;display:block;border:1px solid #536d43;background:#536d43;color:white;padding:13px 24px;font:inherit;border-radius:3px;cursor:pointer}#boldstone-catalogue .catalogue-more[hidden]{display:none}@media(max-width:1000px){#boldstone-catalogue .catalogue-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){#boldstone-catalogue .catalogue-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 14px}#boldstone-catalogue h3{font-size:15px}#boldstone-catalogue label{width:100%}#boldstone-catalogue input,#boldstone-catalogue select{width:100%}}
</style><section id="boldstone-catalogue" aria-label="Wall sculpture catalogue"><div class="catalogue-intro"><h2>Find your wall sculpture</h2><p>Botanical forms, fossil spirals and the movement of water, brought to life through texture, light and shadow. Explore individual wall sculptures for interiors, gardens and outdoor spaces.</p></div><div class="catalogue-filters"><label>Search sculptures<input type="search" placeholder="Try ammonite, leaf or white" aria-label="Search wall sculptures"></label><label>Explore a collection<select aria-label="Wall sculpture collection"><option value="">All collections</option>'''
head+=''.join(f'<option value="{esc(f)}">{esc(f)}</option>' for f in families)
head+='</select></label></div><p class="catalogue-count" aria-live="polite">176 sculptures</p><div class="catalogue-grid">'
cards=[]
for p in products:
 assert p['website_url'].startswith('https://boldstonesculpture.com/buy/p/') and p['existing_images']
 url=p['existing_images'][0]; assert url.startswith('https://images.squarespace-cdn.com/')
 sep='&' if '?' in url else '?';url+=sep+'format=750w'
 cards.append(f'<a class="sculpture-card" href="{esc(p["website_url"])}" data-family="{esc(p["family"])}" data-search="{esc((p["retail_name"]+" "+p["family"]).casefold())}" data-catalogue-id="{esc(p["catalogue_id"])}"><img src="{esc(url)}" loading="lazy" decoding="async" width="750" height="750" alt="{esc(p["retail_name"])}"><h3>{esc(p["retail_name"])}</h3><p class="sculpture-family">{esc(p["family"])}</p></a>')
foot='''</div><button type="button" class="catalogue-more" hidden>Show more sculptures</button></section><script>
(function(){const root=document.getElementById('boldstone-catalogue');if(!root||root.dataset.ready)return;root.dataset.ready='yes';const cards=Array.from(root.querySelectorAll('.sculpture-card'));const search=root.querySelector('input'),family=root.querySelector('select'),more=root.querySelector('.catalogue-more'),count=root.querySelector('.catalogue-count');let limit=24;function render(){const q=search.value.trim().toLocaleLowerCase(),f=family.value;const matches=cards.filter(c=>(!q||c.dataset.search.includes(q))&&(!f||c.dataset.family===f));const visible=new Set(matches.slice(0,limit));for(const c of cards)c.hidden=!visible.has(c);count.textContent=matches.length?'Showing '+Math.min(limit,matches.length)+' of '+matches.length+' sculptures':'No matching sculptures. Try another name or collection.';more.hidden=matches.length<=limit;}search.addEventListener('input',()=>{limit=24;render()});family.addEventListener('change',()=>{limit=24;render()});more.addEventListener('click',()=>{limit+=24;render()});render();})();
</script>'''
(OUT/'homepage-catalogue-block.html').write_text(head+'\n'.join(cards)+foot)
(OUT/'homepage-prepared.json').write_text(json.dumps({'products':176,'families':len(families),'catalogue_ids':[p['catalogue_id'] for p in products],'status':'PREPARED_NOT_PUBLISHED'},indent=2))
print({'products':176,'families':len(families),'bytes':len((head+''.join(cards)+foot).encode())})
